package com.rulecraft.decisionops.tests;

import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.catalog.CatalogService.*;import com.rulecraft.decisionops.catalog.domain.DecisionServiceStatus;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import com.rulecraft.decisionops.runtime.DecisionExecutionService;import com.rulecraft.decisionops.runtime.DecisionExecutionService.EvaluationCommand;import com.rulecraft.decisionops.runtime.types.TypedValueValidator;import com.rulecraft.decisionops.tests.domain.*;import com.rulecraft.decisionops.tests.persistence.*;
import java.time.*;import java.util.*;import java.util.stream.Collectors;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.core.JacksonException;import tools.jackson.core.type.TypeReference;import tools.jackson.databind.*;

@Service
public class DecisionTestService {
    private final DecisionTestCaseRepository tests;private final DecisionTestRunRepository runs;private final ProjectAccessPolicy access;private final CatalogService catalog;private final TypedValueValidator typedValues;private final DecisionExecutionService executions;private final AuditService audit;private final ObjectMapper mapper;private final Clock clock;
    public DecisionTestService(DecisionTestCaseRepository tests,DecisionTestRunRepository runs,ProjectAccessPolicy access,CatalogService catalog,TypedValueValidator typedValues,DecisionExecutionService executions,AuditService audit,ObjectMapper mapper,Clock clock){this.tests=tests;this.runs=runs;this.access=access;this.catalog=catalog;this.typedValues=typedValues;this.executions=executions;this.audit=audit;this.mapper=mapper;this.clock=clock;}
    @Transactional(readOnly=true)public List<TestCaseView> list(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){var service=context(actor,projectId,serviceId,false);return tests.findAllByDecisionServiceIdAndTenantIdAndProjectIdOrderByNameAsc(serviceId,actor.tenantId(),projectId).stream().map(test->view(test,service)).toList();}
    @Transactional public TestCaseView create(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,TestCaseCommand command){var service=context(actor,projectId,serviceId,true);if(tests.countByTenantIdAndDecisionServiceId(actor.tenantId(),serviceId)>=500)bad("RC-TEST-LIMIT","A decision service can contain at most 500 test cases.");var normalized=validate(command,service);if(tests.existsByTenantIdAndDecisionServiceIdAndTestKey(actor.tenantId(),serviceId,normalized.testKey()))conflict("RC-TEST-KEY-EXISTS","A test case already uses this key.");var now=Instant.now(clock);var value=persist(new DecisionTestCase(actor.tenantId(),projectId,serviceId,normalized.testKey(),normalized.name(),normalized.description(),json(normalized.inputs()),json(normalized.expectedOutputs()),actor.userId(),now));audit.record(actor.tenantId(),actor.userId(),"DECISION_TEST_CREATED","DECISION_TEST",value.getId(),Map.of("serviceId",serviceId,"testKey",value.getTestKey()));return view(value,service);}
    @Transactional public TestCaseView update(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID testId,TestCaseCommand command){var service=context(actor,projectId,serviceId,true);var value=require(actor,projectId,serviceId,testId);if(command==null||command.version()==null||command.version()!=value.getVersion())conflict("RC-TEST-STALE","The test case changed. Refresh before saving again.");var normalized=validate(command,service);if(tests.existsByTenantIdAndDecisionServiceIdAndTestKeyAndIdNot(actor.tenantId(),serviceId,normalized.testKey(),testId))conflict("RC-TEST-KEY-EXISTS","A test case already uses this key.");value.update(normalized.testKey(),normalized.name(),normalized.description(),json(normalized.inputs()),json(normalized.expectedOutputs()),TestCaseValidationStatus.VALID,actor.userId(),Instant.now(clock));persist(value);audit.record(actor.tenantId(),actor.userId(),"DECISION_TEST_UPDATED","DECISION_TEST",value.getId(),Map.of("serviceId",serviceId,"testKey",value.getTestKey()));return view(value,service);}
    @Transactional public void remove(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID testId,long version){context(actor,projectId,serviceId,true);var value=require(actor,projectId,serviceId,testId);if(version!=value.getVersion())conflict("RC-TEST-STALE","The test case changed. Refresh before removing it.");tests.delete(value);tests.flush();audit.record(actor.tenantId(),actor.userId(),"DECISION_TEST_REMOVED","DECISION_TEST",testId,Map.of("serviceId",serviceId,"testKey",value.getTestKey()));}
    @Transactional public TestRunView run(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID testId){var service=context(actor,projectId,serviceId,false);var test=require(actor,projectId,serviceId,testId);var inputs=parseMap(test.getInputsJson());var expected=parseMap(test.getExpectedOutputsJson());var issues=inspect(service,inputs,expected);if(!issues.isEmpty())bad("RC-TEST-INVALID","Update this test case to match the current service contract before running it.");var evaluation=executions.evaluate(actor,projectId,serviceId,new EvaluationCommand(inputs));var status=matches(expected,evaluation.outputs())?TestRunStatus.PASSED:TestRunStatus.FAILED;var value=runs.saveAndFlush(new DecisionTestRun(test,evaluation.evaluationId(),evaluation.graphVersion(),status,test.getExpectedOutputsJson(),json(evaluation.outputs()),json(evaluation.decisions()),actor.userId(),Instant.now(clock)));audit.record(actor.tenantId(),actor.userId(),"DECISION_TEST_EXECUTED","DECISION_TEST",testId,Map.of("runId",value.getId(),"status",status.name(),"graphVersion",evaluation.graphVersion(),"testVersion",test.getVersion()));return runView(value);}
    @Transactional(readOnly=true)public List<TestRunView> history(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID testId){context(actor,projectId,serviceId,false);require(actor,projectId,serviceId,testId);return runs.findTop20ByTestCaseIdAndTenantIdOrderByExecutedAtDesc(testId,actor.tenantId()).stream().map(this::runView).toList();}
    private DecisionServiceView context(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,boolean edit){if(edit)access.requireEdit(actor,projectId);else access.requireVisible(actor,projectId);var service=catalog.getService(actor,projectId,serviceId);if(edit&&service.status()!=DecisionServiceStatus.ACTIVE)conflict("RC-TEST-SERVICE-ARCHIVED","Restore the decision service before changing its test cases.");return service;}
    private DecisionTestCase require(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID testId){return tests.findByIdAndDecisionServiceIdAndTenantIdAndProjectId(testId,serviceId,actor.tenantId(),projectId).orElseThrow(()->new DomainProblemException(HttpStatus.NOT_FOUND,"RC-TEST-NOT-FOUND","Test case not found."));}
    private TestCaseCommand validate(TestCaseCommand command,DecisionServiceView service){if(command==null)bad("RC-TEST-BODY","Provide the test case.");var key=command.testKey()==null?"":command.testKey().strip();var name=command.name()==null?"":command.name().strip();var description=command.description()==null||command.description().isBlank()?null:command.description().strip();if(!key.matches("[a-z][A-Za-z0-9_]{0,59}"))bad("RC-TEST-KEY","Test keys use lower camel case with at most 60 letters, numbers, or underscores.");if(name.isBlank()||name.length()>160)bad("RC-TEST-NAME","Test names contain 1–160 characters.");if(description!=null&&description.length()>500)bad("RC-TEST-DESCRIPTION","Test descriptions contain at most 500 characters.");var inputs=command.inputs()==null?Map.<String,JsonNode>of():new LinkedHashMap<>(command.inputs());var expected=command.expectedOutputs()==null?Map.<String,JsonNode>of():new LinkedHashMap<>(command.expectedOutputs());var issues=inspect(service,inputs,expected);if(!issues.isEmpty()){var issue=issues.getFirst();bad(issue.code(),issue.message());}return new TestCaseCommand(command.version(),key,name,description,inputs,expected);}
    private List<TestIssue> inspect(DecisionServiceView service,Map<String,JsonNode> inputs,Map<String,JsonNode> expected){var issues=new ArrayList<TestIssue>();inspectFields("INPUT",service.inputs(),inputs,issues);inspectFields("OUTPUT",service.outputs(),expected,issues);if(json(inputs).length()+json(expected).length()>120_000)issues.add(new TestIssue("RC-TEST-SIZE","The test case input and expected output payload is too large.",null,"TEST"));return issues;}
    private void inspectFields(String target,List<FieldView> fields,Map<String,JsonNode> supplied,List<TestIssue> issues){var definitions=fields.stream().collect(Collectors.toMap(FieldView::fieldKey,field->field));for(var key:supplied.keySet())if(!definitions.containsKey(key))issues.add(new TestIssue("RC-TEST-"+target+"-UNKNOWN","Unknown "+target.toLowerCase(Locale.ROOT)+" field '"+key+"'.",key,target));for(var field:fields){var value=supplied.get(field.fieldKey());if(value==null){if(field.required())issues.add(new TestIssue("RC-TEST-"+target+"-MISSING","Provide required "+target.toLowerCase(Locale.ROOT)+" '"+field.fieldKey()+"'.",field.fieldKey(),target));}else if(!typedValues.valid(value,field.type().builtinType(),field.type().customTypeId()))issues.add(new TestIssue("RC-TEST-"+target+"-TYPE","Field '"+field.fieldKey()+"' does not match its declared type.",field.fieldKey(),target));}}
    private boolean matches(Map<String,JsonNode> expected,Map<String,JsonNode> actual){return expected.entrySet().stream().allMatch(entry->same(entry.getValue(),actual.get(entry.getKey())));}private boolean same(JsonNode expected,JsonNode actual){if(expected==null||actual==null)return expected==actual;if(expected.isNumber()&&actual.isNumber())return expected.decimalValue().compareTo(actual.decimalValue())==0;if(expected.isArray()&&actual.isArray()){if(expected.size()!=actual.size())return false;for(int index=0;index<expected.size();index++)if(!same(expected.get(index),actual.get(index)))return false;return true;}if(expected.isObject()&&actual.isObject()){if(!expected.propertyNames().equals(actual.propertyNames()))return false;return expected.propertyNames().stream().allMatch(key->same(expected.get(key),actual.get(key)));}return expected.equals(actual);}
    private TestCaseView view(DecisionTestCase value,DecisionServiceView service){var inputs=parseMap(value.getInputsJson());var expected=parseMap(value.getExpectedOutputsJson());var issues=inspect(service,inputs,expected);var latest=runs.findFirstByTestCaseIdAndTenantIdOrderByExecutedAtDesc(value.getId(),value.getTenantId()).map(this::runSummary).orElse(null);return new TestCaseView(value.getId(),value.getTestKey(),value.getName(),value.getDescription(),inputs,expected,issues.isEmpty()?TestCaseValidationStatus.VALID:TestCaseValidationStatus.INVALID,issues,latest,value.getUpdatedAt(),value.getVersion());}
    private DecisionTestCase persist(DecisionTestCase value){try{return tests.saveAndFlush(value);}catch(DataIntegrityViolationException failure){conflict("RC-TEST-KEY-EXISTS","A test case already uses this key.");return null;}}
    private TestRunView runView(DecisionTestRun value){return new TestRunView(value.getId(),value.getTestCaseId(),value.getTestCaseVersion(),value.getEvaluationId(),value.getGraphVersion(),value.getStatus(),parseMap(value.getExpectedOutputsJson()),parseMap(value.getActualOutputsJson()),parseList(value.getDecisionResultsJson()),value.getExecutedAt());}private TestRunSummary runSummary(DecisionTestRun value){return new TestRunSummary(value.getId(),value.getStatus(),value.getGraphVersion(),value.getExecutedAt());}
    private String json(Object value){try{return mapper.writeValueAsString(value);}catch(JacksonException failure){throw new IllegalStateException("Test data could not be serialized.",failure);}}private Map<String,JsonNode> parseMap(String raw){try{return mapper.readValue(raw,new TypeReference<LinkedHashMap<String,JsonNode>>(){});}catch(JacksonException failure){throw new IllegalStateException("Persisted test data is invalid.",failure);}}private List<DecisionExecutionService.DecisionEvaluation> parseList(String raw){try{return mapper.readValue(raw,new TypeReference<List<DecisionExecutionService.DecisionEvaluation>>(){});}catch(JacksonException failure){throw new IllegalStateException("Persisted test results are invalid.",failure);}}
    private void bad(String code,String message){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,message);}private void conflict(String code,String message){throw new DomainProblemException(HttpStatus.CONFLICT,code,message);}
    public record TestCaseCommand(Long version,String testKey,String name,String description,Map<String,JsonNode> inputs,Map<String,JsonNode> expectedOutputs){}
    public record TestIssue(String code,String message,String fieldKey,String target){}
    public record TestRunSummary(UUID id,TestRunStatus status,long graphVersion,Instant executedAt){}
    public record TestCaseView(UUID id,String testKey,String name,String description,Map<String,JsonNode> inputs,Map<String,JsonNode> expectedOutputs,TestCaseValidationStatus validationStatus,List<TestIssue> issues,TestRunSummary latestRun,Instant updatedAt,long version){}
    public record TestRunView(UUID id,UUID testCaseId,long testCaseVersion,UUID evaluationId,long graphVersion,TestRunStatus status,Map<String,JsonNode> expectedOutputs,Map<String,JsonNode> actualOutputs,List<DecisionExecutionService.DecisionEvaluation> decisions,Instant executedAt){}
}
